CREATE TABLE "ProductivityCamera" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "branchId" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "sourceType" TEXT NOT NULL DEFAULT 'RTSP', "streamUrlEncrypted" TEXT, "status" TEXT NOT NULL DEFAULT 'OFFLINE', "lastHeartbeatAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ProductivityCamera_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ProductivityCamera_tenantId_branchId_status_idx" ON "ProductivityCamera"("tenantId", "branchId", "status");
CREATE TABLE "ProductivityZone" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "branchId" TEXT NOT NULL, "cameraId" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "polygonCoordinates" JSONB NOT NULL, "zoneType" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ProductivityZone_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ProductivityZone_tenantId_cameraId_status_idx" ON "ProductivityZone"("tenantId", "cameraId", "status");
CREATE TABLE "ProductivityEvent" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "branchId" TEXT NOT NULL, "cameraId" TEXT NOT NULL, "zoneId" TEXT, "employeeId" TEXT, "idempotencyKey" TEXT NOT NULL, "eventType" TEXT NOT NULL, "startedAt" TIMESTAMP(3) NOT NULL, "endedAt" TIMESTAMP(3), "durationSeconds" INTEGER, "confidence" DOUBLE PRECISION, "metadata" JSONB, "source" TEXT NOT NULL DEFAULT 'CV_SERVICE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProductivityEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ProductivityEvent_tenantId_idempotencyKey_key" ON "ProductivityEvent"("tenantId", "idempotencyKey");
CREATE INDEX "ProductivityEvent_tenantId_branchId_startedAt_idx" ON "ProductivityEvent"("tenantId", "branchId", "startedAt");
CREATE TABLE "ProductivitySummary" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "branchId" TEXT NOT NULL, "zoneId" TEXT, "employeeId" TEXT, "date" TIMESTAMP(3) NOT NULL, "activeSeconds" INTEGER NOT NULL DEFAULT 0, "idleSeconds" INTEGER NOT NULL DEFAULT 0, "taskCount" INTEGER NOT NULL DEFAULT 0, "averageTaskDuration" DOUBLE PRECISION, "productivityScore" DOUBLE PRECISION, "confidence" DOUBLE PRECISION, "calculatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProductivitySummary_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ProductivitySummary_tenantId_branchId_date_idx" ON "ProductivitySummary"("tenantId", "branchId", "date");
CREATE TABLE "ProductivityAlertRule" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "branchId" TEXT, "zoneId" TEXT, "name" TEXT NOT NULL, "ruleType" TEXT NOT NULL, "threshold" INTEGER NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ProductivityAlertRule_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ProductivityAlertRule_tenantId_enabled_idx" ON "ProductivityAlertRule"("tenantId", "enabled");
CREATE TABLE "ProductivityAlert" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "branchId" TEXT NOT NULL, "cameraId" TEXT, "zoneId" TEXT, "ruleId" TEXT, "status" TEXT NOT NULL DEFAULT 'OPEN', "title" TEXT NOT NULL, "description" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "acknowledgedAt" TIMESTAMP(3), "closedAt" TIMESTAMP(3), CONSTRAINT "ProductivityAlert_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ProductivityAlert_tenantId_branchId_status_createdAt_idx" ON "ProductivityAlert"("tenantId", "branchId", "status", "createdAt");
